    "environment_setup": {
      "python_version": "3.12+",
      "required_tools": ["uv", "bun"],
      "setup_steps": [
        "git clone https://github.com/ValueCell-ai/valuecell.git && cd valuecell",
        "cp .env.example .env and configure API keys and preferences"
      ],
      "start_application_commands": {
        "linux_macOS": "bash start.sh",
        "windows_powershell": ".\\start.ps1"
