      "ci": "ubuntu-latest",
      "python_version_source": "python/pyproject.toml",
      "install_dependencies": "uv sync --locked --all-extras --dev",
      "test_command": "uv run pytest valuecell/core/ --cov=valuecell.core --cov-report=xml --cov-report=term",
      "coverage_threshold": "90%",
      "working_directory": "./python"
    },
    "start_sh_summary": {
      "auto_install_tools": ["bun", "uv"],
      "backend_setup": [
        "bash scripts/prepare_envs.sh",
        "uv run valuecell/server/db/init_db.py"
      ],
      "frontend_setup": "bun install",
      "backend_start": "uv run --with questionary scripts/launch.py"
    },
    "recommended_test_execution_command": "cd python; uv run pytest server/api/routers/tests/test_user_profile_api.py"
  },
  "terminate": true
}
